public class ReaderBoundaryQA{static final String H=String.join("",Collections.nCopies(64,"a"));static JSONObject link(){return new JSONObject(Values.json(Values.map("run","run","epoch","epoch","boot","boot","generation","gen","operator","op","profileId","profile","APSHA256",H,"configSHA256",H,"surveyRevision",1,"surveySHA256",H)));}static JSONObject terminal(File d)throws Exception{return new JSONObject(Values.json(Values.map("run","run","epoch","epoch","boot","boot","generation","gen","closed",true,"firstFailure",null,"journal",Values.map("commitAnchor",Values.hash(Files.readAllBytes(new File(d,"session.json").toPath()))))));}static void sync(File f,byte[]b)throws Exception{try(FileOutputStream o=new FileOutputStream(f)){o.write(b);o.getFD().sync();}}static String fail(File d)throws Exception{try{vn.rtr.aeris.cockpit04.ClosedReview.build(d,link(),terminal(d));throw new AssertionError("ACCEPTED_BAD");}catch(IOException e){return e.getMessage();}}public static void main(String[]a)throws Exception{File d=new File(a[0]),scratch=new File(a[1]);scratch.mkdirs();ArrayList<Object>out=new ArrayList<>();byte[]good=vn.rtr.aeris.cockpit04.ClosedReview.build(d,link(),terminal(d));out.add(Values.map("id","baseline33MiBCurrent","pass",new JSONObject(new String(good,"UTF-8")).getInt("groundDistinctFreshGroups")==2));File[]segments=d.listFiles((x,n)->n.startsWith("segment-")&&n.endsWith("jsonl"));Arrays.sort(segments,Comparator.comparing(File::getName));File last=segments[segments.length-1];byte[]original=Files.readAllBytes(last.toPath()),bad=original.clone();int offset=new String(bad,"UTF-8").lastIndexOf("PADDING_TEST");if(offset<0)throw new AssertionError("NO_TAIL_PADDING");bad[offset]='X';try{sync(last,bad);String reason=fail(d);out.add(Values.map("id","deepTailAfter32MiBNotSkipped","pass",reason.equals("REVIEW_RECORD_CHAIN"),"reason",reason,"file",last.getName(),"offset",offset,"beforeSHA",Values.hash(original),"mutationSHA",Values.hash(bad)));}finally{sync(last,original);}File first=segments[0];original=Files.readAllBytes(first.toPath());try{sync(first,Arrays.copyOf(original,1048577));String reason=fail(d);out.add(Values.map("id","segment1MiBplus1","pass",reason.equals("REVIEW_SEGMENT_PATH_BOUND"),"reason",reason));}finally{sync(first,original);}original=Files.readAllBytes(first.toPath());try{sync(first,new byte[0]);String reason=fail(d);out.add(Values.map("id","emptySegmentRejected","pass",reason.equals("REVIEW_SEGMENT_PATH_BOUND"),"reason",reason));}finally{sync(first,original);}Class<?>c=Class.forName("vn.rtr.aeris.cockpit04.ClosedReview$BoundedLines");Constructor<?>ctor=c.getDeclaredConstructor(File.class);ctor.setAccessible(true);Method next=c.getDeclaredMethod("next"),close=c.getDeclaredMethod("close");next.setAccessible(true);close.setAccessible(true);byte[][]cases={new byte[]{(byte)128,10},new byte[]{65},new byte[32770]};String[]expected={"REVIEW_UTF8","REVIEW_TRUNCATED_LINE","REVIEW_LINE_BOUND"};Arrays.fill(cases[2],(byte)65);cases[2][32769]=10;for(int i=0;i<cases.length;i++){File f=new File(scratch,"line"+i);sync(f,cases[i]);Object reader=ctor.newInstance(f);String reason="";try{next.invoke(reader);}catch(InvocationTargetException e){reason=e.getCause().getMessage();}finally{close.invoke(reader);}out.add(Values.map("id","streamBoundary"+i,"pass",reason.equals(expected[i]),"reason",reason));}out.add(Values.map("id","fixtureRestoredExact","pass",Arrays.equals(good,vn.rtr.aeris.cockpit04.ClosedReview.build(d,link(),terminal(d)))));System.out.println(Values.json(Values.map("results",out)));}}
